// @title My Game
let x = 76;
let y = 68;
let gx = 14;
let gy = 8;
let gems = 0;

function draw() {
  put(1, 1, 'GEMS ' + gems);
  put(gx, gy, '💎', 4);
}

draw();

function tick() {
  x = Math.max(0, Math.min(152, x + btn(3) - btn(2)));
  y = Math.max(0, Math.min(136, y + btn(1) - btn(0)));

  if (Math.abs(x - gx * 8) < 6 && Math.abs(y - gy * 8) < 6) {
    put(gx, gy, ' ');
    gems += 1;
    gx = Math.floor(Math.random() * 20);
    gy = 2 + Math.floor(Math.random() * 16);
    draw();
    play(0, 'T240V12O6N1cG');
  }

  spr(x, y, '👾', 6);
}

// @title Gems
// ⬆⬇⬅➡ move; Ⓐ dashes, Ⓑ restarts. Collect the gems before time runs out.

const rounds = [
  { gems: 5, seconds: 15 },
  { gems: 7, seconds: 18 },
  { gems: 9, seconds: 21 },
];

let x;
let y;
let gx;
let gy;
let round = 0;
let score = 0;
let collected;
let time;
let dash;
let cooldown;
let state;
let status;

function drawStatus() {
  const seconds = Math.ceil(time / 60);
  const rows = [0, 1];
  const messages = [
    `ROUND ${round + 1}/${rounds.length} GEMS ${collected}/${rounds[round].gems}`,
    `TIME ${seconds}  SCORE ${score}`,
  ];
  if (state === 'PLAY') {
    rows.push(17);
    messages.push(cooldown ? `WAIT ${Math.ceil(cooldown / 60)}  Ⓑ RESTART` : 'READY  Ⓑ RESTART');
  }
  for (const [i, message] of messages.entries()) {
    if (status[i] !== message) {
      put(1, rows[i], message.padEnd(18), 7, 1);
      status[i] = message;
    }
  }
}

function placeGem() {
  gx = Math.floor(Math.random() * 20);
  gy = 2 + Math.floor(Math.random() * 14);
  // Keep a new gem far enough away to require another move.
  if (Math.abs(x - gx * 8) < 24 && Math.abs(y - gy * 8) < 24) {
    gx = gx < 10 ? 19 : 0;
  }
  put(gx, gy, '💎', null, 1);
}

function startRound() {
  x = 76;
  y = 68;
  gx = 4;
  gy = 5;
  collected = 0;
  time = rounds[round].seconds * 60;
  dash = 0;
  cooldown = 0;
  state = 'PLAY';
  status = [];

  cls(1);
  put(gx, gy, '💎', null, 1);
  put(1, 16, '⬆⬇⬅➡ MOVE Ⓐ DASH', 7, 1);
  drawStatus();
  for (let ch = 0; ch < 3; ch++) play(ch, ch === 0 ? 'T240' : '');
}

function reset() {
  round = 0;
  score = 0;
  startRound();
}

function finish(next) {
  state = next;
  const bonus = Math.ceil(time / 60);
  if (next !== 'OVER') score += bonus;
  const messages = {
    CLEAR: [`CLEAR! BONUS +${bonus}`, 'Ⓐ NEXT  Ⓑ RESTART'],
    WON: [`ALL CLEAR! +${bonus}`, 'Ⓐ / Ⓑ PLAY AGAIN'],
    OVER: ['TIME UP!', 'Ⓐ / Ⓑ TRY AGAIN'],
  };
  const [message, hint] = messages[next];
  put(1, 16, ' '.repeat(18), 7, 1);
  put(Math.floor((20 - message.length) / 2), 16, message, next === 'OVER' ? 3 : 6, 1);
  put(1, 17, ' '.repeat(18), 7, 1);
  put(Math.floor((20 - hint.length) / 2), 17, hint, 7, 1);
  drawStatus();
  play(0, next === 'OVER' ? 'T180V12O3N2gec' : 'T180V12O5N2cegC');
}

reset();

function tick() {
  if (btnp(5)) {
    reset();
  } else if (state !== 'PLAY' && btnp(4)) {
    if (state === 'CLEAR') {
      round++;
      startRound();
    } else {
      reset();
    }
  } else if (state === 'PLAY') {
    // At 60 ticks per second, a dash lasts 0.3 seconds and recharges in 1.5.
    if (cooldown > 0) cooldown--;
    if (btnp(4) && cooldown === 0) {
      dash = 18;
      cooldown = 90;
      play(2, 'V10O4N1cG');
    }
    const speed = dash > 0 ? 3 : 1;
    if (dash > 0) dash--;
    x = Math.max(0, Math.min(152, x + (btn(3) - btn(2)) * speed));
    y = Math.max(16, Math.min(120, y + (btn(1) - btn(0)) * speed));
    time--;

    if (Math.abs(x - gx * 8) < 6 && Math.abs(y - gy * 8) < 6) {
      collected++;
      score++;
      put(gx, gy, ' ', 7, 1);
      play(1, 'V12O6N1GC');
      if (collected === rounds[round].gems) {
        finish(round === rounds.length - 1 ? 'WON' : 'CLEAR');
      } else {
        placeGem();
      }
    }
    if (state === 'PLAY' && time === 0) finish('OVER');
    drawStatus();
  }

  spr(x, y, '👾', 6);
}

// @title Lights Out
// ⬆⬇⬅➡ select; Ⓐ flips a light and its neighbors. Ⓑ retries the board.

// Reverse these flips to solve each board; PAR is its minimum move count.
const puzzles = [
  [
    [1, 1],
    [3, 3],
  ],
  [
    [0, 0],
    [2, 2],
    [4, 4],
  ],
  [
    [0, 4],
    [1, 1],
    [3, 3],
    [4, 0],
  ],
  [
    [0, 2],
    [2, 0],
    [2, 2],
    [2, 4],
    [4, 2],
  ],
  [
    [0, 0],
    [1, 3],
    [2, 1],
    [2, 4],
    [3, 2],
    [4, 4],
  ],
];

let level = 0;
let x;
let y;
let moves;
let cleared;
let board;

// Four 8×8 characters form each 16×16 lamp, with four pixels between lamps.
const lampPatterns = [
  '071f3f7f7fffffff',
  'e0f8fcfefeffffff',
  'ffffff7f7f3f1f07',
  'fffffffefefcf8e0',
  '0718204040808080',
  'e018040202010101',
  '8080804040201807',
  '01010102020418e0',
];
for (const [i, chr] of [...'①②③④⑤⑥⑦⑧'].entries()) pcg[chr].pat = lampPatterns[i];
pcg['┌'].pat = 'f880808080000000';
pcg['┐'].pat = '1f01010101000000';
pcg['└'].pat = '00000080808080f8';
pcg['┘'].pat = '000000010101011f';

function flip(cx, cy) {
  for (const [dx, dy] of [
    [0, 0],
    [0, -1],
    [0, 1],
    [-1, 0],
    [1, 0],
  ]) {
    const nx = cx + dx;
    const ny = cy + dy;
    if (nx >= 0 && nx < 5 && ny >= 0 && ny < 5) {
      board[ny][nx] = !board[ny][nx];
    }
  }
}

function isClear() {
  return board.every((row) => row.every((light) => !light));
}

function drawStatus() {
  const last = level === puzzles.length - 1;
  const messages = [
    `LIGHTS OUT ${level + 1}/${puzzles.length}`,
    `MOVES ${moves}  PAR ${puzzles[level].length}`,
    cleared ? (last ? 'ALL BOARDS CLEAR!' : 'BOARD CLEAR!') : 'TURN ALL LIGHTS OFF',
    cleared ? (last ? 'Ⓐ AGAIN  Ⓑ RESTART' : 'Ⓐ NEXT  Ⓑ RETRY') : '⬆⬇⬅➡ Ⓐ FLIP Ⓑ RETRY',
  ];
  for (const [i, row] of [0, 1, 16, 17].entries()) {
    put(0, row, ' '.repeat(20));
    put(Math.floor((20 - messages[i].length) / 2), row, messages[i], i === 0 ? 6 : 7);
  }
}

function startPuzzle() {
  x = 2;
  y = 2;
  moves = 0;
  cleared = false;
  board = Array.from({ length: 5 }, () => Array(5).fill(false));

  cls(0);
  for (const [cx, cy] of puzzles[level]) flip(cx, cy);
  drawStatus();
  play(0, '');
}

startPuzzle();

function tick() {
  if (btnp(5)) {
    if (cleared && level === puzzles.length - 1) level = 0;
    startPuzzle();
  } else if (cleared) {
    if (btnp(4)) {
      level = (level + 1) % puzzles.length;
      startPuzzle();
    }
  } else {
    x = Math.max(0, Math.min(4, x + btnp(3) - btnp(2)));
    y = Math.max(0, Math.min(4, y + btnp(1) - btnp(0)));
    if (btnp(4)) {
      flip(x, y);
      moves++;
      cleared = isClear();
      drawStatus();
      play(0, cleared ? 'T240V12O5N2cegC' : 'T240V10O5N1c');
    }
  }

  for (let cy = 0; cy < 5; cy++) {
    for (let cx = 0; cx < 5; cx++) {
      spr(32 + cx * 20, 24 + cy * 20, board[cy][cx] ? '①②\n③④' : '⑤⑥\n⑦⑧', board[cy][cx] ? 6 : 4);
    }
  }
  const px = 32 + x * 20;
  const py = 24 + y * 20;
  spr(px - 2, py - 2, '┌', 7);
  spr(px + 10, py - 2, '┐', 7);
  spr(px - 2, py + 10, '└', 7);
  spr(px + 10, py + 10, '┘', 7);
}

// @title Snake
// ⬆⬇⬅➡ turn; Ⓐ starts or pauses. Ⓑ restarts.

const width = 18;
const height = 14;
const directions = [
  [0, -1],
  [0, 1],
  [-1, 0],
  [1, 0],
];
const opposite = [1, 0, 3, 2];

let body = [];
let food;
let direction = 3;
let nextDirection = 3;
let frame = 0;
let score = 0;
let state = 'READY';

function chooseFood() {
  const empty = [];
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      if (!body.some((cell) => cell.x === x && cell.y === y)) {
        empty.push({ x, y });
      }
    }
  }
  // Choosing from empty cells also handles a completely filled board.
  if (empty.length === 0) {
    return null;
  }
  return empty[Math.floor(Math.random() * empty.length)];
}

function drawGems() {
  put(11, 0, `GEMS ${score}`);
  if (food) {
    put(1 + food.x, 2 + food.y, '💎', 4);
  }
}

function drawBoard() {
  for (let y = 0; y < height; y++) {
    put(1, 2 + y, ' '.repeat(width));
  }
  drawGems();
  for (let i = 0; i < body.length; i++) {
    put(1 + body[i].x, 2 + body[i].y, '●', i === 0 ? 6 : 5);
  }

  if (state === 'PAUSED') {
    put(7, 8, 'PAUSED', 7, 0);
  } else if (state === 'OVER') {
    put(5, 8, 'GAME OVER', 3, 0);
  } else if (state === 'WON') {
    put(5, 8, 'ALL CLEAR!', 6, 0);
  }
  const action = { READY: 'START', PLAY: 'PAUSE', PAUSED: 'RESUME', OVER: 'RETRY', WON: 'AGAIN' }[
    state
  ];
  put(2, 17, `Ⓐ ${action.padEnd(6)} Ⓑ RESET`);
}

function reset() {
  // The first array element is the head; the last is the tail.
  body = [
    { x: 8, y: 6 },
    { x: 7, y: 6 },
    { x: 6, y: 6 },
  ];
  direction = 3;
  nextDirection = 3;
  frame = 0;
  score = 0;
  state = 'READY';
  food = chooseFood();

  cls(0);
  put(1, 0, 'SNAKE', 6);
  put(0, 1, '▓'.repeat(20), 1);
  put(0, height + 2, '▓'.repeat(20), 1);
  for (let y = 0; y < height; y++) {
    put(0, 2 + y, '▓', 1);
    put(19, 2 + y, '▓', 1);
  }
  drawBoard();
  play(0, '');
}

function move() {
  const [dx, dy] = directions[nextDirection];
  const x = body[0].x + dx;
  const y = body[0].y + dy;
  const grows = x === food.x && y === food.y;

  // The tail leaves its cell on a move that does not eat food.
  const occupied = grows ? body : body.slice(0, -1);
  if (
    x < 0 ||
    x >= width ||
    y < 0 ||
    y >= height ||
    occupied.some((cell) => cell.x === x && cell.y === y)
  ) {
    state = 'OVER';
    drawBoard();
    play(0, 'T180V10O3N1gc');
    return;
  }

  direction = nextDirection;
  body.unshift({ x, y });
  if (!grows) {
    const tail = body.pop();
    put(1 + tail.x, 2 + tail.y, ' ');
  }
  put(1 + body[1].x, 2 + body[1].y, '●', 5);
  put(1 + x, 2 + y, '●', 6);

  if (grows) {
    score += 1;
    play(0, 'T240V10O6N1cG');
    food = chooseFood();
    if (food) {
      drawGems();
    } else {
      state = 'WON';
      drawBoard();
      play(0, 'T180V10O5N3cegC');
    }
  }
}

reset();

function tick() {
  if (btnp(5)) {
    reset();
  }
  if (btnp(4)) {
    if (state === 'PLAY') {
      state = 'PAUSED';
    } else {
      if (state === 'OVER' || state === 'WON') {
        reset();
      }
      state = 'PLAY';
    }
    drawBoard();
  }

  if (state === 'PLAY') {
    for (let id = 0; id < 4; id++) {
      // Compare with the last move, so quick turns cannot reverse into the neck.
      if (btnp(id) && id !== opposite[direction]) {
        nextDirection = id;
      }
    }
    frame += 1;
    if (frame % 8 === 0) {
      move();
    }
  }
}

// @title Shooter
// ⬅➡ move; hold Ⓐ to fire. Ⓑ starts a new game.

const waves = [
  { rows: 1, columns: 6, speed: 0.4, fireEvery: 96 },
  { rows: 2, columns: 5, speed: 0.5, fireEvery: 80 },
  { rows: 2, columns: 6, speed: 0.6, fireEvery: 64 },
  { rows: 1, columns: 1, speed: 1.2, fireEvery: 40, health: 24 },
];

let wave = 0;
let score = 0;
let lives = 3;
let state;
let x;
let frame;
let direction;
let invincible;
let shotDelay;
let targets;
let shots;
let bullets;
let sparks;

pcg['🚀'].pat = [0x18, 0x3c, 0x24, 0x3c, 0x7e, 0xdb, 0x18, 0x24];
pcg['↑'].pat = '1818181818181800';
pcg['↓'].pat = '0018181818181800';
pcg['·'].col = [1, 0];
// Four 8×8 characters make the final wave's 16×16 boss.
pcg['①'].pat = '0103071f3f7f7f6f';
pcg['②'].pat = '80c0e0f8fcfefef6';
pcg['③'].pat = '7f7f3f1f0f1b3300';
pcg['④'].pat = 'fefefcf8f0d8cc00';

function drawStatus() {
  put(1, 0, `WAVE ${wave + 1}/${waves.length}  ♥${lives}`, 6);
  const boss = wave === waves.length - 1 ? ` BOSS ${targets[0].health}` : '';
  put(1, 1, (`SCORE ${String(score).padStart(4, '0')}` + boss).padEnd(19), 7);
  let instruction = '⬅➡ Ⓐ FIRE Ⓑ RESET';
  if (state !== 'PLAY') {
    instruction = state === 'CLEAR' ? 'Ⓐ NEXT Ⓑ RESET' : 'Ⓐ / Ⓑ PLAY AGAIN';
  }
  put(1, 17, ' '.repeat(18), 7, 0);
  put(Math.floor((20 - instruction.length) / 2), 17, instruction, 7, 0);
}

function startWave() {
  const level = waves[wave];
  x = 76;
  frame = 0;
  direction = 1;
  invincible = 60;
  shotDelay = 0;
  state = 'PLAY';
  shots = [];
  bullets = [];
  sparks = [];
  targets = [];

  for (let row = 0; row < level.rows; row++) {
    for (let column = 0; column < level.columns; column++) {
      targets.push({
        x: (152 - (level.columns - 1) * 20) / 2 + column * 20,
        y: 24 + row * 12,
        row,
        column,
        health: level.health || 1,
        alive: true,
      });
    }
  }

  cls(0);
  for (let i = 0; i < 30; i++) {
    scr[3 + (i % 12)][(i * 7) % 20].chr = '·';
  }
  drawStatus();
  for (let ch = 0; ch < 3; ch++) play(ch, ch === 0 ? 'T240M7' : '');
}

function restart() {
  wave = 0;
  score = 0;
  lives = 3;
  startWave();
}

function finish(nextState) {
  state = nextState;
  shots = [];
  bullets = [];
  drawStatus();
  play(2, '');
  play(0, state === 'OVER' ? 'T180M7V12O3N2gec' : 'T240M7V12O5N2cegC');
}

restart();

function tick() {
  if (btnp(5)) {
    restart();
  }
  if (state !== 'PLAY') {
    if (btnp(4)) {
      if (state === 'CLEAR') {
        wave++;
        startWave();
      } else {
        restart();
      }
    }
  } else {
    const level = waves[wave];
    frame++;
    invincible = Math.max(0, invincible - 1);
    shotDelay = Math.max(0, shotDelay - 1);
    x = Math.max(0, Math.min(152, x + (btn(3) - btn(2)) * 2));

    if (btn(4) && shotDelay === 0 && shots.length < 8) {
      shots.push({ x, y: 112 });
      shotDelay = 12;
      play(1, 'V8O6N1G');
    }

    const alive = targets.filter((target) => target.alive);
    if (
      alive.some(
        (target) =>
          target.x + direction * level.speed < 4 || target.x + direction * level.speed > 148,
      )
    ) {
      direction *= -1;
      for (const target of alive) target.y += 4;
    }
    for (const target of alive) target.x += direction * level.speed;

    // Only the lowest alien in a column fires; later waves aim toward the ship.
    if (frame % level.fireEvery === 0) {
      const front = alive.filter(
        (target) => !alive.some((other) => other.column === target.column && other.y > target.y),
      );
      const target = front[Math.floor(Math.random() * front.length)];
      const aim = wave < 2 ? 0 : Math.max(-0.8, Math.min(0.8, (x - target.x) / 90));
      for (const spread of level.health ? [-0.8, 0, 0.8] : [0]) {
        bullets.push({ x: target.x, y: target.y + (level.health ? 16 : 8), dx: aim + spread });
      }
    }

    for (const shot of shots) {
      shot.y -= 4;
      const hit = alive.find(
        (target) =>
          target.alive &&
          Math.abs(target.x - shot.x) < (level.health ? 10 : 6) &&
          Math.abs(target.y - shot.y) < (level.health ? 10 : 6),
      );
      if (hit) {
        hit.health--;
        hit.alive = hit.health > 0;
        shot.y = -8;
        score += 10;
        sparks.push({ x: hit.x, y: hit.y, time: 12 });
        drawStatus();
        play(2, 'M7V12O4N1gc');
      }
    }
    shots = shots.filter((shot) => shot.y >= 16);

    for (const bullet of bullets) {
      bullet.x += bullet.dx;
      bullet.y += 1.5 + wave * 0.2;
      if (!invincible && Math.abs(bullet.x - x) < 6 && Math.abs(bullet.y - 120) < 6) {
        lives--;
        invincible = 90;
        bullets = [];
        drawStatus();
        play(2, 'M35V10O2N1cM7');
      }
    }
    bullets = bullets.filter((bullet) => bullet.y < 128 && bullet.x > -8 && bullet.x < 160);

    if (
      lives === 0 ||
      alive.some((target) => target.alive && target.y + (level.health ? 16 : 8) >= 120)
    ) {
      finish('OVER');
    } else if (targets.every((target) => !target.alive)) {
      score += lives * 100;
      finish(wave === waves.length - 1 ? 'WON' : 'CLEAR');
    }
  }

  for (const target of targets) {
    if (!target.alive) continue;
    if (waves[wave].health) {
      spr(target.x - 4, target.y, '①②\n③④', 3);
    } else {
      spr(target.x, target.y, '👾', [3, 5, 4][target.row]);
    }
  }
  for (const shot of shots) spr(shot.x, shot.y, '↑', 6);
  for (const bullet of bullets) spr(bullet.x, bullet.y, '↓', 3);
  for (const spark of sparks) {
    spark.time--;
    spr(spark.x, spark.y, '✴', spark.time > 6 ? 6 : 3);
  }
  sparks = sparks.filter((spark) => spark.time > 0);
  if (state !== 'OVER' && (invincible % 8 < 4 || state !== 'PLAY')) spr(x, 120, '🚀', 4);
  if (state !== 'PLAY') {
    const message = { CLEAR: 'WAVE CLEAR', WON: 'ALL WAVES CLEAR', OVER: 'GAME OVER' }[state];
    const left = Math.floor((20 - message.length) / 2) * 8;
    // A solid sprite strip keeps the message above aliens and hit particles.
    spr(left, 64, '█'.repeat(message.length), 0);
    spr(left, 64, message, state === 'OVER' ? 3 : 6);
  }
}

// @title Jump
// ⬅➡ move, Ⓐ jumps, Ⓑ retries. Reach all four flags.

const stages = [
  {
    name: 'FIRST STEPS',
    platforms: [
      [1, 14, 5],
      [8, 11, 4],
      [14, 8, 5],
    ],
    flag: [17, 7],
  },
  {
    name: 'SWITCHBACK',
    platforms: [
      [4, 14, 5],
      [11, 11, 3],
      [5, 8, 3],
      [12, 5, 3],
    ],
    flag: [13, 4],
  },
  {
    name: 'FERRY',
    platforms: [
      [1, 14, 5],
      [15, 8, 4],
    ],
    flag: [17, 7],
    ferry: { x: 48, y: 88, width: 24, min: 48, max: 104, dx: 0.75 },
  },
  {
    name: 'PATROL',
    platforms: [
      [3, 14, 4],
      [8, 11, 5],
      [14, 8, 3],
      [7, 5, 3],
    ],
    flag: [8, 4],
    hazard: { x: 84, y: 80, min: 64, max: 96, dx: 0.6 },
  },
];

let stage = 0;
let state;
let x, y, dy;
let grounded, standing;
let jumpBuffer, coyote;
let platforms, ferry, hazard;

pcg['🚩'].pat = '7c7c7c4040404000';

function finish(result) {
  state = result;
  const last = stage === stages.length - 1;
  const message = result === 'OVER' ? 'TRY AGAIN!' : last ? 'ALL CLEAR!' : 'STAGE CLEAR!';
  const hint = result === 'OVER' ? 'Ⓐ / Ⓑ RETRY' : last ? 'Ⓐ / Ⓑ PLAY AGAIN' : 'Ⓐ NEXT  Ⓑ RETRY';
  put(0, 1, ' '.repeat(20));
  put(Math.floor((20 - message.length) / 2), 1, message, 6);
  put(0, 16, ' '.repeat(20));
  put(Math.floor((20 - hint.length) / 2), 16, hint);
  play(0, result === 'OVER' ? 'T240V10O4N1gec' : 'T240V12O5N1cegC');
}

function reset() {
  const level = stages[stage];
  x = (level.platforms[0][0] + 1) * 8;
  y = 104;
  dy = 0;
  grounded = true;
  standing = null;
  jumpBuffer = 0;
  coyote = 0;
  state = 'PLAY';

  // Level data uses cells; movement and collision use pixels.
  platforms = level.platforms.map(([cx, cy, width]) => ({
    x: cx * 8,
    y: cy * 8,
    width: width * 8,
  }));
  ferry = level.ferry ? { ...level.ferry } : null;
  hazard = level.hazard ? { ...level.hazard } : null;

  cls(0);
  const title = `${stage + 1}/${stages.length} ${level.name}`;
  put(Math.floor((20 - title.length) / 2), 1, title, 6);
  put(2, 4, '·', 1);
  put(17, 3, '★', 1);
  for (const platform of platforms) {
    put(platform.x / 8, platform.y / 8, '▀'.repeat(platform.width / 8), 5, 1);
  }
  if (ferry) platforms.push(ferry);
  put(level.flag[0], level.flag[1], '🚩', 3);
  put(0, 15, '~'.repeat(20), 3);
  put(1, 16, '⬅➡ Ⓐ JUMP Ⓑ RETRY');
  play(0, '');
}

function advance(object) {
  if (!object) return 0;
  const previous = object.x;
  object.x += object.dx;
  if (object.x < object.min || object.x > object.max) {
    object.x = Math.max(object.min, Math.min(object.max, object.x));
    object.dx = -object.dx;
  }
  return object.x - previous;
}

function update() {
  const shift = advance(ferry);
  advance(hazard);
  if (ferry && standing === ferry) x += shift;
  x += (btn(3) - btn(2)) * 2;
  x = Math.max(0, Math.min(152, x));

  // Brief input buffering and coyote time make edge jumps forgiving.
  jumpBuffer = btnp(4) ? 6 : Math.max(0, jumpBuffer - 1);
  coyote = grounded ? 5 : Math.max(0, coyote - 1);
  if (jumpBuffer && coyote) {
    dy = -4.8;
    jumpBuffer = 0;
    coyote = 0;
    play(0, 'T240V10O5N1c');
  }

  const previousBottom = y + 8;
  dy = Math.min(dy + 0.28, 4);
  y += dy;
  grounded = false;
  standing = null;
  if (y < 16) {
    y = 16;
    dy = 0;
  }

  // These are one-way platforms: land when falling feet cross their top.
  for (const platform of platforms) {
    if (
      dy >= 0 &&
      previousBottom <= platform.y &&
      y + 8 >= platform.y &&
      x + 8 > platform.x &&
      x < platform.x + platform.width
    ) {
      y = platform.y - 8;
      dy = 0;
      grounded = true;
      standing = platform;
      break;
    }
  }

  if (y >= 120 || (hazard && Math.abs(x - hazard.x) < 6 && Math.abs(y - hazard.y) < 6)) {
    finish('OVER');
  } else {
    const [fx, fy] = stages[stage].flag;
    if (Math.abs(x - fx * 8) < 7 && Math.abs(y - fy * 8) < 7) {
      finish(stage === stages.length - 1 ? 'DONE' : 'CLEAR');
    }
  }
}

reset();

function tick() {
  if (btnp(5) || (state !== 'PLAY' && btnp(4))) {
    if (state === 'DONE') stage = 0;
    else if (state === 'CLEAR' && btnp(4) && !btnp(5)) stage++;
    reset();
  } else if (state === 'PLAY') {
    update();
  }

  if (ferry) spr(ferry.x, ferry.y, '▀'.repeat(ferry.width / 8), 4);
  if (hazard) spr(hazard.x, hazard.y, '💀', 3);
  if (state !== 'OVER') spr(x, y, '👾', 6);
}

