pcg['#'].pat = pcg['▓'].pat;

function drawStatus() {
  const finalStage = stage === levels.length - 1;
  let title = 'GLYPH QUEST';
  let controls = 'Ⓐ STUN   Ⓑ RETRY';
  if (state === 'CAUGHT') {
    title = 'CAUGHT!';
    controls = 'Ⓑ RETRY';
  } else if (state === 'CLEAR') {
    title = finalStage ? 'ALL CLEAR!' : 'STAGE CLEAR!';
    controls = finalStage ? 'Ⓐ RESTART Ⓑ RETRY' : 'Ⓐ NEXT   Ⓑ RETRY';
  }
  const recharge = state === 'PLAY' ? (cooldown ? ' / WAIT' : ' / READY') : '';

  put(1, 0, title.padEnd(18), state === 'CAUGHT' ? 3 : 6);
  put(16, 0, `${stage + 1}/${levels.length}`, 7);
  put(1, 1, `💎${gems}/${total} + 💍 → 🏰`.padEnd(18));
  put(8, 1, '💍', ring ? 6 : 2);
  put(1, 16, ' '.repeat(18));
  put(Math.floor((20 - controls.length) / 2), 16, controls);
  put(1, 17, (levels[stage].name + recharge).padEnd(18), 2);
}

function startLevel() {
  // All map symbols are single code points, so spread keeps the emoji intact.
  map = levels[stage].map.map((row) => [...row]);
  enemies = levels[stage].patrols.map((route) => ({
    route,
    next: 1,
    x: route[0][0],
    y: route[0][1],
    stun: 0,
  }));
  x = 1;
  y = 1;
  frame = 0;
  gems = 0;
  cooldown = 0;
  total = map.flat().filter((chr) => chr === '💎').length;
  ring = false;
  state = 'PLAY';

  pcg['#'].col = [levels[stage].wall, 0];
  cls(0);
  put(0, 2, map.map((row) => row.join('')).join('\n'));
  drawStatus();
  for (let ch = 0; ch < 3; ch++) {
    play(ch, ch === 0 ? 'T240M7' : '');
  }
}

startLevel();

function tick() {
  if (btnp(5)) {
    startLevel();
  } else if (state === 'CLEAR' && btnp(4)) {
    stage = (stage + 1) % levels.length;
    startLevel();
  } else if (state === 'PLAY') {
    frame++;
    if (cooldown > 0) {
      cooldown--;
      if (cooldown === 0) {
        drawStatus();
      }
    }
    if (btnp(4) && cooldown === 0) {
      cooldown = 90;
      for (const enemy of enemies) {
        if (Math.abs(enemy.x - x) + Math.abs(enemy.y - y) <= 3) {
          enemy.stun = 60;
        }
      }
      drawStatus();
      play(0, 'T240V10O6N1cG');
    }

    const previousX = x;
    const previousY = y;
    if (frame % 7 === 0) {
      const dx = btn(3) - btn(2);
      const dy = dx === 0 ? btn(1) - btn(0) : 0;
      const nx = x + dx;
      const ny = y + dy;
      if (map[ny]?.[nx] && map[ny][nx] !== '#') {
        x = nx;
        y = ny;
      }
    }

    let caught = false;
    for (const enemy of enemies) {
      const oldX = enemy.x;
      const oldY = enemy.y;
      if (enemy.stun > 0) {
        enemy.stun--;
      } else if (frame % (22 - stage * 3) === 0) {
        const [tx, ty] = enemy.route[enemy.next];
        enemy.x += Math.sign(tx - enemy.x);
        enemy.y += Math.sign(ty - enemy.y);
        if (enemy.x === tx && enemy.y === ty) {
          enemy.next = (enemy.next + 1) % enemy.route.length;
        }
      }
      if (
        enemy.stun === 0 &&
        ((enemy.x === x && enemy.y === y) ||
          (oldX === x && oldY === y && enemy.x === previousX && enemy.y === previousY))
      ) {
        caught = true;
      }
    }

    const tile = map[y][x];
    if (caught) {
      state = 'CAUGHT';
      drawStatus();
      play(1, 'V10O3N1gc');
    } else if (tile === '💎' || tile === '💍') {
      if (tile === '💎') {
        gems++;
      } else {
        ring = true;
      }
      map[y][x] = ' ';
      put(x, 2 + y, ' ');
      drawStatus();
      play(1, tile === '💎' ? 'V12O6N1ceG' : 'V12O5N1gBG');
    } else if (tile === '🏰' && ring && gems === total) {
      state = 'CLEAR';
      drawStatus();
      play(0, 'T150V12O5N3cegCN5G');
      play(2, 'V10O3N3cegCN5G');
    }
  }

  // The map starts at cell (0, 2); convert sprite coordinates to pixels.
  if (state !== 'CLEAR') {
    for (const enemy of enemies) {
      spr(enemy.x * 8, 16 + enemy.y * 8, '👻', enemy.stun ? 4 : 3);
    }
  }
  spr(x * 8, 16 + y * 8, '👾', state === 'CAUGHT' ? 2 : 6);
}

// @title Sound FX
// ⬆⬇ select an effect. Ⓐ plays it; Ⓑ stops it.

let selected = 0;
let pulse = 0;

// Every tone effect restores M7; M8 gives channel 0 noise instead of tone.
const effects = [
  { name: 'COIN', sound: 'T180M7V12O6N1cG' },
  { name: 'JUMP', sound: 'T180M7V10O4N1cdefg' },
  { name: 'LASER', sound: 'T180M7V12O7N1Cbagfedc' },
  { name: 'HIT', sound: 'T180M8UX1800W0O3N1c' },
  { name: 'POWER UP', sound: 'T180M7V12O5N1cegC' },
  { name: 'VICTORY', sound: 'T150M7V12O5N3cegCN5G' },
];

function putCentered(cy, str, col = 7) {
  put(1, cy, ' '.repeat(18));
  put(Math.floor((20 - str.length) / 2), cy, str, col);
}

function drawEffect() {
  const [settings, notes] = effects[selected].sound.split(/(?=O)/);
  putCentered(13, settings);
  putCentered(14, notes, 6);
}

put(6, 1, 'SOUND FX', 6);
putCentered(2, 'READY');
for (let i = 0; i < effects.length; i++) {
  put(7, 4 + i, effects[i].name, i === selected ? 6 : 7);
}
putCentered(12, 'ZX 128 PLAY', 2);
put(5, 15, '⬆⬇ SELECT');
put(3, 16, 'Ⓐ PLAY  Ⓑ STOP');
drawEffect();

function tick() {
  const previous = selected;
  selected += btnp(1) - btnp(0);
  selected = Math.max(0, Math.min(effects.length - 1, selected));

  if (selected !== previous) {
    pulse = 0;
    put(7, 4 + previous, effects[previous].name, 7);
    put(7, 4 + selected, effects[selected].name, 6);
    drawEffect();
  }

  if (btnp(4)) {
    play(0, effects[selected].sound);
    putCentered(2, `PLAY ${effects[selected].name}`);
    pulse = 18;
  }
  if (btnp(5)) {
    play(0, '');
    putCentered(2, 'STOPPED');
    pulse = 0;
  }

  spr(40, 32 + selected * 8, '→', pulse ? 7 : 6);
  if (pulse > 0) {
    spr(128, 32 + selected * 8 - pulse / 3, '♪', 6);
    pulse--;
  }
}

// @title Music Box
// ⬅➡ select a step; ⬆⬇ change its note. Ⓐ plays or stops; Ⓑ resets.

const pitches = ['&', 'c', 'd', 'e', 'f', 'g', 'a', 'b', 'C'];
const initialNotes = [1, 3, 5, 8, 6, 5, 1, 0];
let notes = initialNotes.slice();
let selected = 0;
let playing = false;
let frame = 0;

function startMusic() {
  const melody = notes.map((note) => pitches[note]).join('');
  play(1, '');
  play(0, 'T120M7V12O5N5' + melody + '))');
  playing = true;
  frame = 0;
}

function stopMusic() {
  play(0, '');
  play(1, '');
  playing = false;
}

function drawNotes() {
  // At 120 BPM, a quarter note lasts 30 ticks.
  const current = Math.floor(frame / 30) % notes.length;
  for (let note = 0; note < pitches.length; note++) {
    for (let step = 0; step < notes.length; step++) {
      const col1 = playing && step === current ? 6 : 4;
      const col2 = step === selected ? 1 : 0;
      const chr = notes[step] === note ? (note === 0 ? '–' : '♪') : '·';
      put(3 + step * 2, 12 - note, chr, col1, col2);
    }
  }
  put(2, 16, playing ? 'Ⓐ STOP  Ⓑ RESET' : 'Ⓐ PLAY  Ⓑ RESET');
}

put(5, 1, 'MUSIC BOX', 6);
put(3, 3, '8 STEPS');
put(12, 3, '– REST', 2);
for (let note = 0; note < pitches.length; note++) {
  put(1, 12 - note, note === 0 ? '–' : pitches[note], 2);
}
for (let step = 0; step < notes.length; step++) {
  put(3 + step * 2, 13, String(step + 1), 2);
}
put(2, 15, 'STEP ⬅➡ NOTE ⬆⬇');
drawNotes();

function tick() {
  const previousSelected = selected;
  selected = Math.max(0, Math.min(notes.length - 1, selected + btnp(3) - btnp(2)));
  if (selected !== previousSelected) {
    drawNotes();
  }

  const previous = notes[selected];
  notes[selected] = Math.max(0, Math.min(pitches.length - 1, notes[selected] + btnp(0) - btnp(1)));
  if (notes[selected] !== previous) {
    if (playing) {
      startMusic();
    } else {
      play(1, 'M7V10O5N1' + pitches[notes[selected]]);
    }
    drawNotes();
  }

  if (btnp(4)) {
    if (playing) {
      stopMusic();
    } else {
      startMusic();
    }
    drawNotes();
  }
  if (btnp(5)) {
    stopMusic();
    notes = initialNotes.slice();
    selected = 0;
    frame = 0;
    drawNotes();
  }

  if (playing) {
    frame++;
    if (frame % 30 === 0) {
      drawNotes();
    }
  }
}

